mapper.select:
SELECT wo.work_order_id, wo.work_order_no, wo.product_id, wo.product_code, wo.product_name, wo.plan_qty, wo.status, IFNULL(p.yield_model, '2') AS yield_model, p.schedule_mode, p.std_yield_rate, p.yield_alarm_rate, wo.qualified_qty AS actual_qty, (SELECT IFNULL(SUM(d.issue_qty), 0) FROM mms_issue_detail d JOIN mms_issue i ON d.issue_id = i.issue_id AND i.del_flag = '0' WHERE i.work_order_id = wo.work_order_id AND d.del_flag = '0') AS input_qty, (SELECT IFNULL(SUM(t.loss_qty), 0) FROM food_wip_transfer t WHERE t.work_order_id = wo.work_order_id AND t.del_flag = '0' AND t.loss_type = '1') AS loss_cut, (SELECT IFNULL(SUM(t.loss_qty), 0) FROM food_wip_transfer t WHERE t.work_order_id = wo.work_order_id AND t.del_flag = '0' AND t.loss_type = '2') AS loss_salt, (SELECT IFNULL(SUM(t.loss_qty), 0) FROM food_wip_transfer t WHERE t.work_order_id = wo.work_order_id AND t.del_flag = '0' AND t.loss_type = '3') AS loss_ferment, (SELECT IFNULL(SUM(t.loss_qty), 0) FROM food_wip_transfer t WHERE t.work_order_id = wo.work_order_id AND t.del_flag = '0' AND t.loss_type = '4') AS loss_other, (SELECT IFNULL(SUM(t.loss_qty), 0) FROM food_wip_transfer t WHERE t.work_order_id = wo.work_order_id AND t.del_flag = '0') AS loss_total FROM mms_work_order wo LEFT JOIN food_material_param p ON p.material_id = wo.product_id AND p.del_flag = '0'
wo.del_flag = '0' AND wo.work_order_no LIKE CONCAT('%', #{workOrderNo}, '%') AND wo.product_code LIKE CONCAT('%', #{productCode}, '%') AND wo.product_name LIKE CONCAT('%', #{productName}, '%') AND p.yield_model = #{yieldModel} AND wo.status = #{status} AND date(wo.create_time) >= #{params.beginTime} AND date(wo.create_time) <= #{params.endTime}
ORDER BY wo.work_order_id DESC
